// Author: MiYu. Execute explicit ordered player commands against live session permissions and state.
#include "player_commands.h"
#include "session.h"
#include <algorithm>
#include <bit>
#include <cmath>

namespace war3 {
unsigned dispatchPlayerCommand(ScriptSession& session,const PlayerCommand& command) {
    if(command.player>=16)return 0;switch(command.kind){case PlayerCommandKind::SetAlliance:return session.setAllianceOption(command.player,command.otherPlayer,command.allianceOption,command.enabled)?1u:0u;case PlayerCommandKind::SetAlliedVictory:return session.setAlliedVictory(command.player,command.enabled)?1u:0u;case PlayerCommandKind::TransferResources:return session.transferResources(command.player,command.otherPlayer,command.gold,command.lumber)?1u:0u;case PlayerCommandKind::Chat:if(command.text.empty() || command.text.size()>1024)return 0;session.chat(command.player,command.text);return 1;default:break;}bool hasPoint=command.kind==PlayerCommandKind::GroundMove || command.kind==PlayerCommandKind::GroundAttack || command.kind==PlayerCommandKind::GroundPatrol || command.kind==PlayerCommandKind::SpellPoint || command.kind==PlayerCommandKind::BuildAt || command.kind==PlayerCommandKind::ItemPoint;bool spell=command.kind==PlayerCommandKind::SpellUnit || command.kind==PlayerCommandKind::SpellPoint || command.kind==PlayerCommandKind::SpellImmediate;bool inventory=command.kind==PlayerCommandKind::ItemImmediate || command.kind==PlayerCommandKind::ItemUnit || command.kind==PlayerCommandKind::ItemPoint || command.kind==PlayerCommandKind::DropItem;bool purchase=command.kind==PlayerCommandKind::PurchaseItem || command.kind==PlayerCommandKind::PurchaseUnit;bool production=command.kind==PlayerCommandKind::Train || command.kind==PlayerCommandKind::Research || command.kind==PlayerCommandKind::Upgrade || command.kind==PlayerCommandKind::CancelUpgrade || command.kind==PlayerCommandKind::CancelBuild || command.kind==PlayerCommandKind::CancelProduction || command.kind==PlayerCommandKind::Revive || command.kind==PlayerCommandKind::ReturnResources || command.kind==PlayerCommandKind::LearnSkill;if(!hasPoint && !spell && !production && !inventory && !purchase && command.kind!=PlayerCommandKind::Stop && command.kind!=PlayerCommandKind::Hold && command.kind!=PlayerCommandKind::TargetOrder && command.kind!=PlayerCommandKind::UnloadUnit && command.kind!=PlayerCommandKind::AbilityAutocast && command.kind!=PlayerCommandKind::RepairAutocast)return 0;if(hasPoint && (!std::isfinite(std::bit_cast<float>(command.xBits)) || !std::isfinite(std::bit_cast<float>(command.yBits))))return 0;if((command.kind==PlayerCommandKind::TargetOrder && (!command.target || !command.order)) || ((command.kind==PlayerCommandKind::SpellUnit || command.kind==PlayerCommandKind::ItemUnit || command.kind==PlayerCommandKind::UnloadUnit) && !command.target) || (inventory && !command.item) || (purchase && !command.objectType) || (spell && !command.ability) || ((command.kind==PlayerCommandKind::BuildAt || command.kind==PlayerCommandKind::Train || command.kind==PlayerCommandKind::Research || command.kind==PlayerCommandKind::Upgrade || command.kind==PlayerCommandKind::Revive || command.kind==PlayerCommandKind::LearnSkill) && !command.objectType))return 0;WorldPoint point{jass::Real::fromBits(command.xBits),jass::Real::fromBits(command.yBits)};unsigned accepted=0;
    for(auto id:command.units){auto found=session.units().find(id);if(found==session.units().end() || (!purchase && !session.canControlUnit(command.player,*found->second)))continue;auto unit=found->second;bool issued=false;switch(command.kind){case PlayerCommandKind::GroundMove:issued=unit->stationaryBuilding()?session.setRally(id,point):session.moveUnit(id,point);break;case PlayerCommandKind::GroundAttack:issued=session.attackMove(id,point);break;case PlayerCommandKind::GroundPatrol:issued=session.attackMove(id,point,true);break;case PlayerCommandKind::Stop:issued=session.stopUnit(id);break;case PlayerCommandKind::Hold:issued=session.stopUnit(id,true);break;case PlayerCommandKind::TargetOrder:issued=session.targetOrder(id,command.target,command.order);break;case PlayerCommandKind::SpellUnit:issued=session.castSpell(id,command.ability,command.target);break;case PlayerCommandKind::SpellPoint:issued=session.castSpellAt(id,command.ability,point);break;case PlayerCommandKind::SpellImmediate:issued=session.castSpell(id,command.ability);break;case PlayerCommandKind::BuildAt:issued=session.build(id,command.objectType,point);break;case PlayerCommandKind::Train:issued=session.train(id,command.objectType);break;case PlayerCommandKind::Research:issued=session.research(id,command.objectType);break;case PlayerCommandKind::Upgrade:issued=session.upgradeBuilding(id,command.objectType);break;case PlayerCommandKind::CancelUpgrade:issued=session.cancelBuildingUpgrade(id);break;case PlayerCommandKind::CancelBuild:issued=session.cancelConstruction(id);break;case PlayerCommandKind::CancelProduction:issued=session.cancelProduction(id,command.queueIndex);break;case PlayerCommandKind::Revive:issued=session.queueRevival(id,command.objectType);break;case PlayerCommandKind::ReturnResources:issued=session.returnResources(id);break;case PlayerCommandKind::LearnSkill:issued=session.canManageUnitInventory(command.player,*unit) && session.learnHeroSkill(id,command.objectType);break;case PlayerCommandKind::ItemImmediate:case PlayerCommandKind::ItemUnit:case PlayerCommandKind::ItemPoint:case PlayerCommandKind::DropItem:{auto item=session.items().find(command.item);if(!session.canManageUnitInventory(command.player,*unit) || item==session.items().end() || item->second->holder!=id)break;if(command.kind==PlayerCommandKind::DropItem){if(std::find(unit->inventory.begin(),unit->inventory.end(),command.item)==unit->inventory.end())break;session.dropItem(id,command.item);issued=true;}else if(command.kind==PlayerCommandKind::ItemPoint)issued=session.useItemAt(id,command.item,point);else issued=session.useItem(id,command.item,command.kind==PlayerCommandKind::ItemUnit?command.target:0);break;}case PlayerCommandKind::AbilityAutocast:issued=command.ability && session.abilityAutocast(id,command.ability,command.enabled);break;case PlayerCommandKind::RepairAutocast:issued=session.repairAutocast(id,command.enabled);break;case PlayerCommandKind::UnloadUnit:{auto passenger=session.units().find(command.target);if(passenger!=session.units().end() && passenger->second->transport==id)issued=session.unloadUnit(id,command.target);break;}case PlayerCommandKind::PurchaseItem:case PlayerCommandKind::PurchaseUnit:issued=session.purchase(id,command.player,command.objectType,command.kind==PlayerCommandKind::PurchaseItem);break;case PlayerCommandKind::SetAlliance:case PlayerCommandKind::SetAlliedVictory:case PlayerCommandKind::TransferResources:case PlayerCommandKind::Chat:break;}if(issued){++accepted;if(command.stopOnSuccess)break;}}return accepted;
}
}
